[CmdletBinding()]
param([Parameter(Mandatory)][string]$RunId,[string]$CampaignPath='',[string]$SimionExe='')
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
$projectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$repoRoot=(Resolve-Path (Join-Path $projectRoot '..\..')).Path;$workspaceRoot=(Resolve-Path (Join-Path $repoRoot '..')).Path
. (Join-Path $repoRoot 'common\require_powershell7.ps1');. (Join-Path $repoRoot 'common\contracts\run_artifact_support.ps1');. (Join-Path $repoRoot 'common\host_execution_lease.ps1')
$python=Join-Path $repoRoot '.venv\Scripts\python.exe';if(-not$SimionExe){$SimionExe=Join-Path $env:ProgramFiles 'SIMION-2020\simion.exe'};foreach($item in @($python,$SimionExe)){if(-not(Test-Path -LiteralPath $item -PathType Leaf)){throw "Required executable is missing: $item"}}
$campaign=if($CampaignPath){(Resolve-Path -LiteralPath $CampaignPath).Path}else{Join-Path $projectRoot 'config\two_zone_component_focus_campaign.json'};$builder=Join-Path $projectRoot 'simion\build_component_focus_pa.lua';$artifactRoot=Join-Path $workspaceRoot 'artifacts';$cacheRoot=Join-Path $artifactRoot 'common\simion\pa_family_cache'
$package=New-RunPackage -Python $python -RepoRoot $repoRoot -ArtifactRoot (Join-Path $artifactRoot 'projects\orthogonal_accelerator') -RunId $RunId -Project orthogonal_accelerator -Mode component_focus_pa_build -Software @('SIMION 2020','Python 3.11') -RetentionContractEnabled -RetentionClass solver_review -RetentionReason 'One provider-owned closed-two-zone native controller for component focus; runtime flights use in-memory Fast Adjust.' -CapacityLedgerLifecycleEnabled -AdditionalDirectories @('simion') -UseShortExecutionPath
$lease=$null;$capacity=$null;$retention=$null;$terminalized=$false;$temporary=$null;$verificationEvidence=$null;$stage='preflight';$failureDetail=''
function Invoke-RootPython([string[]]$Arguments){Push-Location $repoRoot;try{&$python @Arguments;if($LASTEXITCODE-ne0){throw "Python stage failed: $($Arguments -join ' ')"}}finally{Pop-Location}}
try{
 $capacity=Enter-ArtifactWorkflowCapacitySession -Python $python -RepoRoot $repoRoot -ArtifactRoot $artifactRoot -RunDirectory $package.artifact_run_dir -CommittedNewBytes 0 -Owner "orthogonal-accelerator-focus-pa:$RunId"
 $stage='freeze_inputs';$frozenCampaign=Copy-VerifiedRunInput $campaign (Join-Path $package.input_dir 'campaign.json');$frozenPlanSource=Copy-VerifiedRunInput (Join-Path $projectRoot 'analysis\component_focus_pa_plan.py') (Join-Path $package.input_dir 'component_focus_pa_plan.py');$frozenCacheSource=Copy-VerifiedRunInput (Join-Path $projectRoot 'analysis\component_focus_pa_cache.py') (Join-Path $package.input_dir 'component_focus_pa_cache.py');$frozenBuilder=Copy-VerifiedRunInput $builder (Join-Path $package.input_dir 'build_component_focus_pa.lua');$frozenVerifier=Copy-VerifiedRunInput (Join-Path $projectRoot 'simion\verify_component_focus_pa.lua') (Join-Path $package.input_dir 'verify_component_focus_pa.lua')
 $plan=Join-Path $package.result_dir 'component_focus_pa_plan.json';Invoke-RootPython @('-m','projects.orthogonal_accelerator.analysis.component_focus_pa_plan','--campaign',$frozenCampaign,'--output',$plan)
 $probeText=@(Invoke-RootPython @('-m','projects.orthogonal_accelerator.analysis.component_focus_pa_cache','--action','probe','--cache-root',$cacheRoot,'--plan',$plan,'--builder',$frozenBuilder,'--simion-executable',$SimionExe);$null)|Out-String
 $probe=($probeText.Trim()|ConvertFrom-Json);$identity=Join-Path $package.result_dir 'component_focus_pa_cache_identity.json';$probe.identity|ConvertTo-Json -Depth 30|Set-Content $identity -Encoding utf8
 $domain=$probe.identity.grid_phase.pa_span_mm;$mesh=$probe.identity.mesh.mm_per_gu;[int64]$nodes=1;for($i=0;$i-lt3;$i++){$nodes*=[int64]([math]::Round([double]$domain[$i]/[double]$mesh[$i])+1)};[int64]$required=if($probe.disposition-eq'hit'){0}else{3*11*$nodes*8}
 $stage='capacity_startup';$updated=Update-ArtifactWorkflowCapacitySession -Python $python -RepoRoot $repoRoot -Session $capacity -ProtectedCacheKeys @([string]$probe.cache_key) -RemainingCommittedNewBytes $required;$capacity=$updated.session;Write-RunJson -Path (Join-Path $package.result_dir 'artifact_capacity_gate_startup.json') -Depth 14 -Value $updated
 # Capacity-ledger terminal publication requires this immutable retention
 # receipt. Create it while this run contains only frozen light inputs, before
 # any private native PA or cache publication exists.
 $stage='retention_prebuild';$retention=Apply-RunArtifactRetention -Python $python -RepoRoot $repoRoot -RunConfig $package.run_config
 if($probe.disposition-eq'hit'){$publication=$probe}else{
   if($probe.disposition-ne'miss'){throw "Focus-controller cache is not usable: $($probe.disposition)"};$stage='transaction_start';$transactionText=@(Invoke-RootPython @('-m','projects.orthogonal_accelerator.analysis.component_focus_pa_cache','--action','advance-transaction','--cache-root',$cacheRoot,'--plan',$plan,'--builder',$frozenBuilder,'--simion-executable',$SimionExe,'--owner',$capacity.owner,'--producer-run-config',$package.run_config);$null)|Out-String;$transaction=($transactionText.Trim()|ConvertFrom-Json);if($transaction.action_required-ne'build'){throw "Focus PA transaction cannot build: $($transaction.action_required)"};$stage='native_build';$temporary=Join-Path ([IO.Path]::GetTempPath()) ('orthogonal_accelerator_focus_pa_'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $temporary|Out-Null;$gem=Join-Path $temporary 'orthogonal_accelerator_focus.gem';$planDocument=Get-Content -Raw $plan|ConvertFrom-Json -Depth 30;Set-Content -LiteralPath $gem -Value ([string]$planDocument.gem) -Encoding ascii;$raw=Join-Path $transaction.build_directory 'orthogonal_accelerator_focus.pa#';$lease=Enter-HostExecutionLease -Role SIMION -Stage pa_refine -RunId $RunId;Push-Location $temporary;try{&$SimionExe --nogui --noprompt lua $frozenBuilder $gem $raw 2>&1|Tee-Object (Join-Path $package.log_dir 'build_component_focus_pa.log');if($LASTEXITCODE-ne0){throw 'Native focus controller build failed'}}finally{Pop-Location};$stage='seal_and_verify';$sealedText=@(Invoke-RootPython @('-m','projects.orthogonal_accelerator.analysis.component_focus_pa_cache','--action','advance-transaction','--cache-root',$cacheRoot,'--plan',$plan,'--builder',$frozenBuilder,'--simion-executable',$SimionExe,'--owner',$capacity.owner);$null)|Out-String;$sealed=($sealedText.Trim()|ConvertFrom-Json);if($sealed.action_required-ne'verify'){throw "Focus PA transaction cannot verify: $($sealed.action_required)"};$verificationOutput=Join-Path $package.log_dir 'verify_component_focus_pa.log';&$SimionExe --nogui --noprompt lua $frozenVerifier $raw 2>&1|Tee-Object $verificationOutput;if($LASTEXITCODE-ne0){throw 'Native focus controller verification failed'};$verificationEvidence=Join-Path $package.result_dir 'component_focus_pa_verification.json';[ordered]@{schema_version=1;role='simion_pa_family_verification';status='pass';cache_key=[string]$sealed.cache_key;inventory_sha256=[string]$sealed.inventory_sha256;solver_release='SIMION 2020';verifier_path=(Resolve-Path $frozenVerifier).Path;verifier_sha256=(Get-FileHash $frozenVerifier -Algorithm SHA256).Hash;verification_output_path=(Resolve-Path $verificationOutput).Path;verification_output_sha256=(Get-FileHash $verificationOutput -Algorithm SHA256).Hash}|ConvertTo-Json -Depth 8|Set-Content $verificationEvidence -Encoding utf8;$stage='publish';$publicationText=@(Invoke-RootPython @('-m','projects.orthogonal_accelerator.analysis.component_focus_pa_cache','--action','advance-transaction','--cache-root',$cacheRoot,'--plan',$plan,'--builder',$frozenBuilder,'--simion-executable',$SimionExe,'--owner',$capacity.owner,'--verification-evidence',$verificationEvidence);$null)|Out-String;$publication=($publicationText.Trim()|ConvertFrom-Json);if($publication.action_required-ne'complete'){throw "Focus PA transaction did not complete publication: $($publication.action_required)"}
 }
 $result=Join-Path $package.result_dir 'component_focus_pa_result.json';$publication|ConvertTo-Json -Depth 30|Set-Content $result -Encoding utf8;$summary=[ordered]@{schema_version=1;role='orthogonal_accelerator_component_focus_pa';status='success';qualification='native_controller_only__focus_flight_pending';cache_key=$publication.cache_key;generation_sha256=$publication.generation_sha256;generation_directory=$publication.generation_directory;native_family_members=@('orthogonal_accelerator_focus.pa#')+@(0..9|ForEach-Object{"orthogonal_accelerator_focus.pa$_"});cache_policy='published_read_only_native_fast_adjust_family__no_detached_response_bank_or_materialization'};Write-RunJson -Path $package.summary -Depth 16 -Value $summary
 $stage='capacity_terminal';$terminal=Update-ArtifactWorkflowCapacitySession -Python $python -RepoRoot $repoRoot -Session $capacity -RemainingCommittedNewBytes 0;$capacity=$terminal.session;Write-RunJson -Path (Join-Path $package.result_dir 'artifact_capacity_gate_terminal.json') -Depth 14 -Value $terminal;$outputs=@($package.summary,$result,$plan,$identity,$retention,(Join-Path $package.result_dir 'artifact_capacity_gate_startup.json'),(Join-Path $package.result_dir 'artifact_capacity_gate_terminal.json'));$buildLog=Join-Path $package.log_dir 'build_component_focus_pa.log';$verifyLog=Join-Path $package.log_dir 'verify_component_focus_pa.log';if(Test-Path -LiteralPath $buildLog -PathType Leaf){$outputs+=@($buildLog)};if(Test-Path -LiteralPath $verifyLog -PathType Leaf){$outputs+=@($verifyLog)};if($verificationEvidence -and(Test-Path -LiteralPath $verificationEvidence -PathType Leaf)){$outputs+=@($verificationEvidence)};Write-VerifiedRunManifest -Python $python -RepoRoot $repoRoot -RunConfig $package.run_config -Status success -Software @('SIMION 2020','Python 3.11') -Outputs $outputs;$terminalized=$true
}catch{$failureDetail=$_.Exception.Message;throw
}finally{if(-not$terminalized){$reason="Focus PA build failed at $stage.";if(-not[string]::IsNullOrWhiteSpace($failureDetail)){$reason+=" $failureDetail"};Complete-FailedRun -Python $python -RepoRoot $repoRoot -RunConfig $package.run_config -Summary $package.summary -SummaryRole orthogonal_accelerator_component_focus_pa -Reason $reason -Software @('SIMION 2020','Python 3.11') -Status failed};if($lease){Exit-HostExecutionLease -Lease $lease -Outcome $(if($terminalized){'success'}else{'failed'}) -RunId $RunId};if($capacity){$null=Exit-ArtifactWorkflowCapacitySession -Python $python -RepoRoot $repoRoot -Session $capacity};if($temporary -and(Test-Path $temporary)){Remove-Item -LiteralPath $temporary -Recurse -Force};Remove-RunPackageExecutionAlias -Package $package}
